-- DRAFTS: a rehearsal file (every draft fact and row). Never apply it to production.
-- L12-L1-sites-live.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   sets sites.status to 'live' for anime and hub. The last launch file: apply it after every other L file and the go check.
-- Needs:  L01 to L11.
-- Verify: select id, status from public.sites order by sort;   expect kpop live, anime live, hub live
-- Undo:   L12-L1-sites-live.rollback.sql (back to building; no data is written by this file).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if (select count(*) from public.sites where id in ('anime', 'hub')) <> 2 then
    raise exception 'L12: the anime and hub rows are missing (apply L01 first)';
  end if;
end $o1l$;

update public.sites set status = 'live' where id in ('anime', 'hub') and status <> 'live';
